          try: "اكتب [[pwd]]، ادخل أي فولدر بـ [[cd]] واكتبه تاني ولاحظ المسار اتغير إزاي.",
          deep: {
            why: "وانت بتستخدم الماوس، الفولدر اللي انت فاتحه قدامك على الشاشة، فعارف انت فين. في الترمنال مفيش شباك بيوريك، فمحتاج طريقة تسأل بيها «انا فين دلوقتي؟». ودي أهم معلومة، لأن كل أمر بتكتبه بيشتغل بالنسبة للمكان ده.",
            how: R`كل ترمنال مفتوح عنده متغير في ذاكرته اسمه «الفولدر الحالي» (current working directory). لما تفتح ترمنال جديد، القيمة دي بتبدأ بفولدرك ([[/home/ali]] مثلًا). [[pwd]] مش بيدوّر على حاجة، هو بس بيطبع القيمة دي.

والمهم تفهم: لما تكتب اسم ملف من غير مسار كامل، زي [[cat notes.txt]]، الشيل بيلزق قبله الفولدر الحالي، فيبقى [[/home/ali/notes.txt]]. عشان كده نفس الأمر ممكن ينجح في فولدر ويفشل في فولدر تاني.

وكل نافذة ترمنال ليها فولدرها الحالي لوحدها. لو فتحت اتنين، ودخلت في واحد [[cd /var/log]]، التاني مش هيتأثر.`,
            when: "أول ما تدخل سيرفر بـ ssh ومش عارف انت فين. قبل أي أمر مسح أو نقل، عشان تتأكد إنك في المكان الصح. ولما أمر يقولك «No such file or directory» وانت متأكد إن الملف موجود، أول سؤال: انت واقف فين أصلًا؟",
            mistakes: "الغلطة الأشهر إنك تفتكر انت في فولدر وانت في فولدر تاني، وتنفّذ أمر مسح أو نقل في المكان الغلط. عوّد نفسك تعمل [[pwd]] قبل أي أمر خطير، أو بص على الـ prompt لأنه غالبًا بيكتب الفولدر."
          },
          lines: ["print working directory: اطبع مسار الفولدر اللي انت فيه كامل."],
          sol: R`هتلاقي [[pwd]] طبع حاجة زي [[/home/ali]] (أو [[/Users/ali]] على الماك)، وبعد [[cd lab]] مثلًا يطبع [[/home/ali/lab]]. المسار اتغير لأن [[cd]] بيغيّر «الفولدر الحالي» بتاع الشيل، و [[pwd]] بيقرا القيمة دي ويطبعها بس.

لو دخلت لينك رمزي (symlink) هتلاقي [[pwd]] بيطبع اسم اللينك مش الفولدر الحقيقي، و [[pwd -P]] بيطبع الحقيقي. ولو [[cd]] قالك No such file or directory، الاسم مش موجود جوه الفولدر اللي انت فيه، والـ [[pwd]] مش هيتغير.`
