          sol: R`بعد [[sudo apt install tree]] (أو [[brew install tree]] على الماك)، اكتب في فولدر المشروع [[tree -L 2 -I node_modules]]. هتشوف الفولدرات ومستوى واحد جواها، وفي الآخر سطر زي [[5 directories, 12 files]]، ومن غير أي أثر لـ node_modules.

لو ظهرلك آلاف السطور يبقى [[-I]] مكتوب غلط (هو حرف I كابيتال والنمط بعده). وعشان تستبعد أكتر من حاجة افصل بـ [[|]] جوه علامات تنصيص: [[tree -L 2 -I 'node_modules|dist']]. و [[tree]] زي [[ls]]، مش بيعرض الملفات المخفية زي [[.env]] إلا بـ [[-a]].`
