            how: R`[[mkdir]] (من make directory) بيطلب من النظام يعمل فولدر فاضي في المسار اللي قلته. لو الفولدر اللي فوقه مش موجود، هيفشل. يعني [[mkdir app/src]] هيفشل لو app مش موجود.

هنا بييجي [[-p]] (من parents): بيقوله «اعمل كل الفولدرات اللي في الطريق لو ناقصة». وكمان بيخليه ميطلعش error لو الفولدر موجود أصلًا، وده بيخليه آمن في السكربتات: تشغّله ١٠ مرات يدّي نفس النتيجة.

والأقواس [[app/{public,logs,tests}]] دي مش حاجة في mkdir، دي حاجة في الشيل نفسه اسمها brace expansion. الشيل بيفكها قبل ما يشغّل mkdir، فـ mkdir بيوصله [[app/public app/logs app/tests]] كأنك كاتبهم بإيدك. تقدر تشوف ده بنفسك: اكتب [[echo app/{public,logs,tests}]].`,
