          sol: R`[[ls app]] هيطبع [[logs  public  src]] (مترتبين أبجديًا مش بترتيب ما كتبتهم). الأقواس [[{src,public,logs}]] مش بتاعة mkdir، الشيل هو اللي بيفردها لـ [[app/src app/public app/logs]] قبل ما mkdir يشتغل، و [[-p]] بيعمل [[app]] نفسه الأول لو مش موجود.

لو لقيت فولدر واحد اسمه حرفيًا [[{src,public,logs}]]، يبقى حطيت مسافة بعد الفاصلة ([[{src, public}]]) أو حطيت النمط جوه علامات تنصيص، والاتنين بيوقفوا الفرد. وتقدر تشوف الفرد قبل التنفيذ بـ [[echo app/{src,public,logs}]].`
