            how: R`لما برنامج يبدأ يستقبل اتصالات، بيطلب من النظام «احجزلي بورت 3000». والنظام بيسمح لبرنامج واحد بس على نفس البورت، عشان لما يجي اتصال يعرف يوديه لمين. عشان كده التاني بيفشل.

[[ss]] بيقرا جدول الاتصالات من النظام نفسه. والاختيارات: [[-t]] اتصالات TCP (المواقع وقواعد البيانات)، و [[-u]] UDP، و [[-l]] اللي بتسمع بس (listening، يعني مستنية حد يكلّمها)، و [[-p]] اسم البرنامج ورقمه، و [[-n]] الأرقام زي ما هي بدل أسامي البورتات.

و [[lsof]] اسمه list open files. في لينكس الاتصالات بتتعامل كأنها ملفات، فـ [[lsof -i :3000]] معناها «مين فاتح ملف من نوع اتصال على بورت 3000».`,
