            how: R`[[ssh]] بيعمل اتصال مشفّر بين جهازك والسيرفر، وأي حاجة تكتبها بتروح متشفّرة وبتتنفذ هناك.

وأأمن طريقة للدخول هي «المفاتيح»، وبتشتغل بزوج مفاتيح: مفتاح خاص (private) بيفضل على جهازك بس ومحدش يشوفه أبدًا، ومفتاح عام (public، الملف اللي آخره .pub) بتحطه على السيرفر. تقدر تدّي المفتاح العام لأي حد، مش خطر.

لما تدخل، السيرفر بيبعتلك «سؤال» متشفّر بالمفتاح العام، ومفيش حد يقدر يحله غير اللي معاه المفتاح الخاص. جهازك بيحله ويرد، فالسيرفر يعرف إنك انت. والمفتاح الخاص نفسه عمره ما بيتبعت على النت.

[[ssh-keygen]] بيعمل الزوج، و [[ssh-copy-id]] بيحط المفتاح العام على السيرفر في ملف اسمه [[~/.ssh/authorized_keys]].

وأول مرة تدخل أي سيرفر، [[ssh]] هيسألك «متأكد؟» ويوريك بصمة السيرفر. لما توافق، بيحفظها. ولو بعدين البصمة اتغيرت، هيوقفك بتحذير كبير، لأن ده معناه إما السيرفر اتعمل من جديد، أو حد بيحاول ينتحل شخصيته.`,
