          sol: R`[[sudo ss -tlnp]] بيطلع سطر لكل بورت بيسمع. بص على عمود [[Local Address:Port]]: [[0.0.0.0:80]] أو [[*:443]] أو [[[::]:22]] يعني مفتوح لكل الشبكات، و [[127.0.0.1:5432]] أو [[[::1]:6379]] يعني من جوه السيرفر بس.

القاعدة: اللي لازم يبقى عام هو 80 و 443 (Nginx أو Caddy) و 22 (SSH). أي داتابيز (5432 و 3306 و 27017) و Redis (6379) وتطبيقك نفسه (3000) لازم يبقوا 127.0.0.1، لأن Nginx هو اللي بيوصلهم. ولو لقيت [[0.0.0.0:5432]] وانت شغال Docker، غالبًا عندك [[ports: "5432:5432"]] في الـ compose؛ خليها [[127.0.0.1:5432:5432]] أو شيلها خالص. وافتكر إن Docker بيعدّي ufw، فالـ firewall مش هيحميك هنا.`
