          sol: R`كل سطر في [[traceroute]] هو hop (راوتر في الطريق) ورقمه والوقت لحد عنده. في الطريقين، أول hop أو اتنين هيبقوا نفس الحاجة: راوتر بيتك ([[192.168.1.1]] مثلًا) وبعده شبكة الـ ISP. بعدها الطريق بيتفرق: جوجل غالبًا قريب لأن عندها سيرفرات في بلاد كتير، وسيرفرك هيعدّي على شبكة الـ datacenter بتاعته، فعدد الـ hops والوقت هيختلفوا. و [[mtr -rwc 10]] بيعمل نفس الحاجة بس بيبعت 10 مرات ويطلّع [[Loss%]] و [[Avg]] لكل hop.

سطور [[* * *]] مش معناها إن الطريق مقطوع؛ راوترات كتير مش بترد على الـ probes دي. اللي يقلق إن الـ loss يبدأ عند hop معين ويفضل لحد آخر سطر، أو الوقت يقفز جامد عند hop ويفضل عالي بعده.`
