            how: R`الـ DNS مش «دليل تليفون» واحد. هو سلسلة: فيه سيرفرات رئيسية (root) بتعرف مين مسؤول عن [[.com]]، وسيرفرات [[.com]] بتعرف مين مسؤول عن [[example.com]]، وده اسمه الـ nameserver بتاعك (غالبًا عند الشركة اللي اشتريت منها الدومين أو Cloudflare)، وهو اللي عنده الإجابة الحقيقية.

وعشان السلسلة دي بطيئة، كل حد في الطريق بيحفظ الإجابة فترة اسمها TTL. عشان كده لما تغيّر الـ DNS، الناس بتشوف الجديد في أوقات مختلفة، حسب إمتى الكاش عندهم خلص. وده «انتشار الـ DNS».

و [[dig]] بيسأل ويوريك الإجابة. [[+short]] الإجابة بس. [[@1.1.1.1]] اسأل سيرفر DNS معين بدل اللي جهازك بيستخدمه، فتقارن. و [[+trace]] بيمشي السلسلة كلها من الأول ويوريك كل خطوة.

وأنواع السجلات: [[A]] الـ IP، و [[MX]] سيرفرات الإيميل، و [[NS]] مين مسؤول عن الدومين، و [[TXT]] نصوص للتحقق (زي تحقق جوجل وإعدادات SPF للإيميل).`,
            when: "بعد أي تغيير DNS: هل اتنشر؟ الإيميل مش بيوصل: [[MX]] و [[TXT]]. قبل certbot: الدومين بيشاور على السيرفر؟",
