          example: R`#!/usr/bin/env bash
log() {
  echo "[$(date '+%H:%M:%S')] $*"
}

folder_size() {
  local dir="$1"
  du -sh "$dir" | cut -f1
}

check_dir() {
  if [[ ! -d "$1" ]]; then
    log "Missing: $1"
    return 1
  fi
}

check_dir /var/www || exit 1
SIZE=$(folder_size /var/www)
log "Size is $SIZE"`,
